// Extract data from incoming webhook from Receiver
const body = $json.body;
let chatId = null;
let messageId = null;
let username = null;
let firstName = null;
let lastName = null;
let isPremium = false;
let languageCode = 'en';
let callbackData = null;

// Check if it's a callback_query (button press)
if (body.callback_query) {
  const callback = body.callback_query;
  const message = callback.message;
  chatId = message.chat.id;
  messageId = message.message_id;
  username = message.chat.username || null;
  firstName = message.chat.first_name || '';
  lastName = message.chat.last_name || '';
  isPremium = callback.from?.is_premium || false;
  languageCode = callback.from?.language_code || 'en';
  callbackData = callback.data;
}
// Check if it's a regular message
else if (body.message) {
  const message = body.message;
  chatId = message.chat.id;
  messageId = message.message_id;
  username = message.chat.username || null;
  firstName = message.chat.first_name || '';
  lastName = message.chat.last_name || '';
  isPremium = message.from?.is_premium || false;
  languageCode = message.from?.language_code || 'en';
}

// Parse callback data: /edit|action|playlistId|trackId
let action = null;
let subAction = null;
let playlistId = null;
let trackId = null;
let context = null;

if (callbackData) {
  const parts = callbackData.split('|');
  subAction = parts[1] && parts[1].length > 0 ? parts[1] : null;

  if (subAction === 'rename') {
    playlistId = parts[2] ? Number(parts[2]) : null;
  } else if (subAction === 'delete') {
    playlistId = parts[2] ? Number(parts[2]) : null;
  } else if (subAction === 'tracks') {
    playlistId = parts[2] ? Number(parts[2]) : null;
  } else if (subAction === 'playlist') {
    playlistId = parts[2] ? Number(parts[2]) : null;
  } else if (subAction === 'confirm') {
    context = parts[2];
    if (context === 'delete') {
      playlistId = parts[3] ? Number(parts[3]) : null;
    } else if (context === 'delete_track') {
      playlistId = parts[3] ? Number(parts[3]) : null;
      trackId = parts[4] ? Number(parts[4]) : null;
    }
  } else if (subAction === 'cancel') {
    context = parts[2];
    if (context === 'delete') {
      playlistId = parts[3] ? Number(parts[3]) : null;
    } else if (context === 'delete_track') {
      playlistId = parts[3] ? Number(parts[3]) : null;
      trackId = parts[4] ? Number(parts[4]) : null;
    } else if (context === 'rename') {
      playlistId = parts[3] ? Number(parts[3]) : null;
    }
  } else if (subAction === 'show_track_for_deletion') {
    playlistId = parts[2] ? Number(parts[2]) : null;
    trackId = parts[3] ? Number(parts[3]) : null;
    action = 'show_track_for_deletion';
  }
}

return [{
  json: {
    chat_id: chatId,
    message_id: messageId,
    username: username,
    first_name: firstName,
    last_name: lastName,
    is_premium: isPremium,
    language_code: languageCode,
    sub_action: subAction,
    action: action,
    context: context,
    playlist_id: playlistId,
    track_id: trackId,
    raw_callback: callbackData
  }
}];

