const callbackData = $('Parse /edit command').first().json.raw_callback || '';
const parts = callbackData.split('|');

const subAction = parts[1] && parts[1].length > 0 ? parts[1] : 'menu';
let action = parts[2] || null;
let context = null;
let playlistId = null;
let trackId = null;
let cancelAction = null;

if (subAction === 'show_track_for_deletion') {
  playlistId = parts[2] ? Number(parts[2]) : null;
  trackId = parts[3] ? Number(parts[3]) : null;
  action = 'show_track_for_deletion';
}
else if (subAction === 'confirm' && parts[2] === 'delete_track') {
  playlistId = parts[3] ? Number(parts[3]) : null;
  trackId = parts[4] ? Number(parts[4]) : null;
  context = 'delete_track';
}
else if (subAction === 'cancel' && parts[2] === 'delete_track') {
  playlistId = parts[3] ? Number(parts[3]) : null;
  trackId = parts[4] ? Number(parts[4]) : null;
  context = 'delete_track';
  cancelAction = 'delete_track';
}
else if (subAction === 'confirm' && parts[2] === 'delete') {
  context = 'delete';
  playlistId = parts[3] ? Number(parts[3]) : null;
}
else if (subAction === 'cancel' && parts[2] === 'delete') {
  context = 'delete';
  playlistId = parts[3] ? Number(parts[3]) : null;
  cancelAction = 'delete_playlist';
}
else if (subAction === 'cancel' && parts[2] === 'rename') {
  context = 'rename';
  playlistId = parts[3] ? Number(parts[3]) : null;
  cancelAction = 'rename_playlist';
}
else if (subAction === 'confirm' || subAction === 'cancel') {
  context = parts[2] || null;
  playlistId = parts[3] ? Number(parts[3]) : null;
}
else {
  playlistId = parts[2] ? Number(parts[2]) : null;
}

if (isNaN(playlistId)) playlistId = null;
if (isNaN(trackId)) trackId = null;

const chatData = $('Parse /edit command').first().json;

return [{
  json: {
    sub_action: subAction,
    action: action,
    context: context,
    cancel_action: cancelAction,
    playlist_id: playlistId,
    track_id: trackId,
    chat_id: chatData.chat_id,
    message_id: chatData.message_id,
    raw_callback: callbackData
  }
}];

